		/** 
		 * Tests creating a new Nonconformance.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Nonconformance");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Nonconformance" );

			try {            
				Nonconformance entity = NonconformanceService.getNonconformanceInstance().createNonconformance( generateNewEntity() );
				thePrimaryKey = entity.getNonconformanceId();
				LOGGER.info( "-- Successfully created a Nonconformance with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Nonconformance. 
		 */
		public Nonconformance testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Nonconformance" );

			Nonconformance entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Nonconformance with primary key" );
			msg.append( thePrimaryKey );
			
			NonconformanceFetchOneSummary fetchOneSummary = new NonconformanceFetchOneSummary( thePrimaryKey );

			try {
				entity = NonconformanceService.getNonconformanceInstance().getNonconformance( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Nonconformance " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Nonconformance.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Nonconformance." );

			StringBuilder msg = new StringBuilder( "Failed to update a Nonconformance : " );        
			Nonconformance entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Nonconformance." );

				// for use later on...
				thePrimaryKey = entity.getNonconformanceId();

				NonconformanceService proxy = NonconformanceService.getNonconformanceInstance();            
				proxy.updateNonconformance( entity );   

				LOGGER.info( "-- Successfully saved Nonconformance - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Nonconformance.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Nonconformance." );

			try{
			    Nonconformance entity = testRead(); 
				NonconformanceService.getNonconformanceInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Nonconformance with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Nonconformance with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Nonconformances.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Nonconformances:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Nonconformance : " );        
			List<Nonconformance> collection  = null;

			try {
				// call the static get method on the NonconformanceService
				collection = NonconformanceService.getNonconformanceInstance().getAllNonconformance();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Nonconformance entity = null;            
					Iterator<Nonconformance> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getNonconformanceId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

